22	/** A single named Git credential entry used to authenticate against a remote host. */
23	interface GitCredentialEntry {
24	    id: string;     // unique identifier; referenced by Repository.CredentialId
25	    label: string;  // human-readable display name shown in the UI
26	    host: string;   // hostname this credential applies to (e.g. "github.com")
27	    token: string;  // Personal Access Token, password, or other credential string
28	}
29	
30	interface AppConfig {
31	    projectsFolder: string;
32	    storageFolder: string;
33	    cloneDepth: number;       // default: 50
34	    serverPort: number;       // default: 4200
35	    gitPollingIntervalSeconds: number; // default: 30
36	    gitCredentials?: GitCredentialEntry[]; // named credential entries; absent or empty = public repos only
37	    maxErrorLogEntries?: number;  // default: 500 — FIFO eviction cap for error log
38	    webserverUrl?: string;  // base URL of local webserver (e.g. http://localhost:8080); absent = Browse button hidden
39	    notesCardHeight: number;  // height (px) of each note card; range [MIN_NOTES_CARD_HEIGHT, MAX_NOTES_CARD_HEIGHT]; default: DEFAULT_NOTES_CARD_HEIGHT (220)
40	    notesColumns: number;     // column count in the notes view grid; range [MIN_NOTES_COLUMNS, MAX_NOTES_COLUMNS]; default: DEFAULT_NOTES_COLUMNS (2)
41	}
42	```
43	
44	> **Credential selection:** Repositories reference a specific credential via `Repository.CredentialId`. When a repository has no `CredentialId`, the tool auto-selects the sole credential whose `host` matches the repository's remote URL (if exactly one such credential exists).
