101	 * @param url   - The remote URL to modify.
102	 * @param token - The credential token to inject.
103	 * @returns The URL with the token injected, or the original URL unchanged for
104	 *   non-HTTPS or malformed URLs.
105	 */
106	export function injectCredentialToken(url: string, token: string): string {
107	    const host = extractHost(url);
108	    if (host === null) return url;
109	
110	    try {
111	        const parsed = new URL(url);
112	        parsed.username = token;
113	        parsed.password = '';
114	        return parsed.toString();
115	    } catch {
116	        return url;
117	    }
118	}
119	
120	/**
121	 * Returns `true` when the URL contains an embedded username (and optional password)
122	 * in the userinfo section (e.g. `https://token@github.com/...`).
123	 *
124	 * Always returns `false` for non-HTTPS or malformed URLs.
125	 *
126	 * @param url - The URL to inspect.
127	 */
128	export function hasEmbeddedCredentials(url: string): boolean {
129	    if (!url) return false;
130	    try {
131	        const parsed = new URL(url);
132	        if (parsed.protocol !== 'https:') return false;
133	        return parsed.username !== '';
134	    } catch {
135	        return false;
136	    }
137	}
138	
139	/**
140	 * Redacts embedded HTTPS credentials from a URL or arbitrary string (e.g. a
141	 * git error message such as `"fatal: repository 'https://token@host/...' not found"`).
142	 *
143	 * Pure HTTPS URLs are sanitised via the WHATWG URL object (clean user/password
144	 * removal). All other inputs — non-HTTPS URLs, prose strings, and unparseable
145	 * values — fall through to a regex scrub that replaces any `https?://…@` pattern
146	 * with `https://***@`, preserving the host and path while redacting the token.
147	 *
148	 * @param input - The URL or string to sanitise.
149	 * @returns The sanitised string, or the original if no embedded credentials are
150	 *   found.
151	 */
152	export function stripEmbeddedCredentials(input: string): string {
153	    if (!input) return input;
154	    try {
155	        const parsed = new URL(input);
156	        if (parsed.protocol === 'https:') {
157	            parsed.username = '';
158	            parsed.password = '';
159	            return parsed.toString();
160	        }
161	        // Non-HTTPS valid URL (e.g. git:// or a prose string the WHATWG parser
162	        // accepted with a non-standard scheme like "fatal:") — fall through to
163	        // the regex scrub below to redact any embedded https credentials.
164	    } catch {
165	        // Not parseable as a URL — fall through to regex scrub.
166	    }
167	    // Scrub any embedded https credential patterns present in prose strings
168	    // (e.g. git error: "fatal: repository 'https://token@host/...' not found").
169	    return input.replace(/(https?:\/\/)[^@\s]*@/g, '$1***@');
170	}

